ight='30' viewBox='0 0 30 30'%3e%3cpath stroke='rgba%280, 0, 0, 0.5%29' stroke-linecap='round' stroke-miterlimit='10' stroke-width='2' d='M4 7h22M4 15h22M4 23h22'/%3e%3c/svg%3e\");\n}\n","/**\n * @file\n * Styles for Bootstrap Barrio's image buttons.\n */\n\n.image-button.is-disabled:hover,\n.image-button.is-disabled:active,\n.image-button.is-disabled:focus,\n.image-button.is-disabled {\n  background: transparent;\n  opacity: 0.5;\n  cursor: default;\n}\n",".image-preview {\n  float: left; /* LTR */\n  padding: 0 10px 10px 0; /* LTR */\n}\n[dir=\"rtl\"] .image-preview {\n  float: right;\n  padding: 0 0 10px 10px;\n}\n.image-widget-data {\n  float: left; /* LTR */\n}\n[dir=\"rtl\"] .image-widget-data {\n  float: right;\n}\n.image-widget-data .text-field {\n  width: auto;\n}\n",".content img {\n  max-width: 100%;\n  height: auto;\n}","/**\n * @file\n * Basic styling for comment module.\n */\n\n/**\n * Indent threaded comments.\n */\n.indented {\n  margin-left: 25px; /* LTR */\n}\n[dir=\"rtl\"] .indented {\n  margin-left: 0;\n  margin-right: 25px;\n}\n","/**\n * @file\n * Visual styles for Bootstrap Barrio's item list.\n */\n\n.item-list ul {\n  list-style: none;\n  margin: 0 0 0.25em 0;\n  padding: 0; /* LTR */\n}\n[dir=\"rtl\"] .item-list ul {\n  padding: 0;\n}\n.item-list ul li {\n  /* This is needed to reset styles in item-list.theme.css */\n  margin: 0;\n  padding: 0.2em 0.5em 0 0; /* LTR */\n}\n[dir=\"rtl\"] .item-list ul li {\n  /* This is needed to reset [dir=\"rtl\"] styles in item-list.theme.css */\n  margin: 0;\n  padding: 0.2em 0 0 0.5em;\n}\n.item-list .item-list__comma-list,\n.item-list .item-list__comma-list li,\n[dir=\"rtl\"] .item-list .item-list__comma-list,\n[dir=\"rtl\"] .item-list .item-list__comma-list li {\n  padding: 0;\n}\n","/**\n * @file\n * List group.\n * A list of links, grouped together.\n */\n\n.list-group__link {\n  border-top: 1px solid #ccc;\n  padding: 7px 0 0;\n}\n.list-group__description {\n  margin: 0 0 10px;\n}\n","/**\n * @file\n * Enables Bootstrap 4 multi-level flyout\n */\n\n/* Only for mobile */\n@media (max-width: 767px) {\n\n  nav.menu--main, nav.menu--fr-main-menu {\n    margin-left: 16px;\n    width: 100%;\n    padding-bottom: 12px;\n\n  }\n  .block-views-exposed-filter-blocksearch-page {\n    margin-left: 16px;\n  }\n  /* Enables first level dropdown from main nav links */\n  a.nav-link .dropdown>.dropdown-menu.show {\n      display: block;\n      border: 0;\n      margin-top: 5px !important;\n  }\n\n  ul.dropdown-menu {\n    border: 0;\n  }\n\n  .dropdown-menu .menu-item--expanded>a:after {\n    visibility: hidden;\n  }\n\n  ul.dropdown-menu.show li.menu-item--expanded>ul.dropdown-menu {\n    display: block;\n    border: 0;\n  }\n\n}\n\n/* Only for non-mobile */\n@media (min-width: 768px) {\n\n  /* Enables first level dropdown from main nav links */\n  .dropdown:hover>.dropdown-menu {\ndisplay: block;\n  }\n.dropdown-menu {\ndisplay:block;\n}\n\n}\n.dropdown-menu {\nborder: none;\nbackground: none !important;\n}\n\n\n/* Force manu items with no link to still use pointer */\nspan.nav-link {\n  cursor: pointer;\n}\n\n.dropdown-menu .menu-item--expanded:hover>a:after {\n  visibility: hidden;\n}\n\n.dropdown-menu .menu-item--expanded:hover {\n  border-right: 1px solid #fff;\n}\n\n/* Enables next level dropdowns to go horizontal */\n.dropdown-menu .menu-item--expanded>.dropdown-menu {\n  top: 0px;\n  left: 100%;\n  margin-top: -1px;\n  margin-left: 0px;\n  -webkit-border-radius: 0;\n  -moz-border-radius: 0;\n  border-radius: 0;\n}\n\n/* Creates right arrow which vanishes on rollover/expansion */\n.dropdown-menu .menu-item--expanded>a:after {\n  display: block;\n  content: \" \";\n  float: right;\n  width: 0;\n  height: 0;\n  border-color: transparent;\n  border-style: solid;\n  border-width: 5px 0 5px 5px;\n  border-left-color: #ccc;\n  margin-top: 7px;\n  margin-right: -5px;\n}\n\n.dropdown-item {\n  padding: 5px 0px;\n}\n/* Remove margin and padding around each flyout's containing UL, so that there is no \"gap\" where hover does not function, and flyouts vanish as you roll over the gap */\nul.dropdown-menu {\n  padding: 0;\n  margin: 0;\n}\n\n/* Make sure links in the active trail reverse out to white so that they do not diappear when the LIs highlight */\n.dropdown-menu li.active>a {\n  color: #fff;\n}\n\n\n.header .nav-link {\n    color: #000;\n    padding: 0;\n}\n\n.header .nav-link a {\n    color: #000;\n}\n\n@media (min-width: 992px) {\n  .navbar-expand-lg .navbar-nav .nav-link {\n  }\n}\n\n@media (min-width: 992px) {\n  .navbar-expand-lg .navbar-toggler {\n    display: inline ;\n  }\n}\n\n.dropdown-menu a {\n    color: #000;\n    text-decoration: none;\n    font-size: 1.5rem;\n}\n.menu--main, .menu--fr-main-menu {\n    margin-top: 3rem;\n\n}\n.navbar-nav {\n\n\n}\n.navbar-nav .nav-link {\n    padding-right: 0;\n    padding-left: 0;\n    font-weight: 900;\n    font-size: 2rem;\n    line-height: 3rem;\n    text-transform: uppercase;\n}\n.navbar-collapse {\n\n    margin-top: 0.5rem;\n    border-radius: 0 0 0.5rem 0.5rem;\n    background: rgba(0, 0, 0, 0.6);\n    backdrop-filter: blur(50px);\n    padding: 2rem;\n\n}\n@media only screen and (max-width: 800px) {\n.navbar-collapse {\n    margin-left: -0.75rem;\n    margin-right: -0.75rem;\n}\n\n}\nheader #search-block-form .btn-outline-primary {\n    color: #000;\n    border-color: #000;\n}\nheader #search-block-form {\n    padding: 0 !important;\n    margin-top: 1rem;\n}\nheader #search-block-form .btn-outline-primary:hover {\n    background-color: #000;\n    border: none;\n}\n\n\n.dropdown-toggle:hover {\ncolor:fff;\n}\n.offcanvas-header .btn-close {\n    postion: absolute;\n\n}\n.btn-check:focus+.btn-outline-primary, .btn-outline-primary:focus {\n  box-shadow: none;\n}\n#CollapsingNavbar {\n    width: 100vw;\n    height: 100vh;\n    min-height: 100vh;\n    min-width: 100vw;\n// background: linear-gradient(to top, rgba(255,255,255,.6),rgba(255,255,255,1));\n\n}\n@media (min-width: 992px)\n {\