rm-control {\n    display: inline;\n    float: left ;\n  }\n  .form-row > fieldset {\n    padding: 0;\n    display: inline;\n    float: left;\n  }\n}\n.btn-outline-primary {\n  border-color: #000;\n}\n.btn-outline-primary:hover {\n  border-color: #000;\n\n}","/**\n * @file\n * Visual styles for Bootstrap Barrio's node component.\n */\n\n.node__content {\n  font-size: 1.071em;\n  margin-top: 10px;\n}\n\n/* View mode teaser styles. */\n.node--view-mode-teaser {\n  border-bottom: 1px solid #d3d7d9;\n  margin-bottom: 30px;\n  padding-bottom: 15px;\n}\n.node--view-mode-teaser h2 {\n  margin-top: 0;\n  padding-top: 0.5em;\n}\n.node--view-mode-teaser h2 a {\n  color: #181818;\n}\n.node--view-mode-teaser.node--sticky {\n  background: #f9f9f9;\n  background: rgba(0, 0, 0, 0.024);\n  border: 1px solid #d3d7d9;\n  padding: 0 15px 15px;\n}\n.node--view-mode-teaser .node__content {\n  clear: none;\n  font-size: 1em;\n  line-height: 1.6;\n}\n\n/* Node metadata styles. */\n.node__meta {\n  font-size: 0.857em;\n  color: #68696b;\n  margin-bottom: -5px;\n}\n.node__meta .field--name-field-user-picture img {\n  float: left; /* LTR */\n  margin: 1px 20px 0 0; /* LTR */\n}\n[dir=\"rtl\"] .node__meta .field--name-field-user-picture img {\n  float: right;\n  margin-left: 20px;\n  margin-right: 0;\n}\n\n/* Node links styles. */\n.node__links {\n  text-align: right; /* LTR */\n  font-size: 0.93em;\n}\n[dir=\"rtl\"] .node__links {\n  text-align: left;\n}\n\n/* Unpublished node styles. */\n.node--unpublished {\n  padding: 20px 15px 0;\n}\n.node--unpublished .comment-text .comment-arrow {\n  border-left: 1px solid #fff4f4;\n  border-right: 1px solid #fff4f4;\n}\n/* Poem page and view styles */\n\n.node--type-poem, .block-views-blockcontent-type-index-pages-block-15, .block-views-blockcontent-type-index-pages-block-3 {\n    .field__label {\n    text-transform: uppercase;  \n    font-family: 'Roboto Flex';\n    font-style: normal;\n    font-weight: 1000;\n    font-size: 18px;\n    line-height: 21px;\n    /* or 117% */\n    letter-spacing: 0.1em;\n    }\n    .field__item a {\n    text-decoration: none;\n  //  border-right: 1px solid #000;\n  //  padding: 0 5px;\n        \n    }\n    .field__item:last-child a::after {\n    content: '';\n    }\n    .field__item a::after {\n    content: ',';\n    }\n    .block-field-blocknodepoembody {\n    padding-bottom: 6rem;\n    border-bottom: 4px dashed rgba(0, 0, 0, 0.4);\n    margin-bottom: 7rem;\n    }\n    .main-content {\n    margin-bottom: 7rem;    \n    }\n    .block-field-blocknodepoembody p, .index-views.poems p {\n      line-height: 30px;\n      padding-left: 1em;\n      text-indent: -1em;\n      margin: 0 !important;\n    }\n    .index-views h2 {\n      color: #000 !important;\n      margin-bottom: 1rem !important;\n    }\n    .block-entity-print, .view-footer {\n      display:none;\n    }\n\n\n}\n\n/* Poet page styles */\n\n.path-user {\n\n    h2 {\n\n        text-transform: uppercase;  \n        font-family: 'Roboto Flex';\n        font-style: normal;\n        font-weight: 1000;\n        font-size: 18px;\n        line-height: 21px;\n        /* or 117% */\n        letter-spacing: 0.1em;\n    }\n    .field__label {\n    font-weight: 700;    \n    }\n    .block-field-blockuseruserfield-micro-interview p {\n    font-size: 17px;\n    line-height: 30px;        \n    }\n    .paragraph--type--publications {\n    margin-bottom: 2rem;\n    border-bottom: 1px solid rgba(0, 0, 0, 0.4);\n    padding-bottom: 2rem;\n\n    }\n    .paragraph--type--publications .field__label, .paragraph--type--publications .field__item {\n    display: inline;\n    padding-left: 0 !important;\n    }\n    .paragraph--type--publications .field__label::after, .field--name-field-photo-credit .field__label::after  {\n    content: ': ';\n    }\n    .block-views-blockcontent-by-author-poems-on-their-page-block-1 {\n    margin-bottom: 4rem;\n    }\n    .block-views-blockcontent-by-author-poems-on-their-page-block-1 .row {\n    border-bottom: 1px solid rgba(0, 0, 0, 0.4);\n    }\n    .block-field-blockuseruserfield-user-bio {\n    border-bottom: 4px dashed rgba(0, 0, 0, 0.4);\n    padding-bottom: 4rem;\n    margin-bottom: 4rem;\n\n    }\n    .block-field-blockuseruserfield-social-links, .block-field-blockuseruserfield-lifespan {\n    display: inline;\n    float: right;\n    font-family: 'Roboto Flex';\n    font-style: normal;\n    font-weight: 400;\n    font-size: 32px;\n    line-height: 34px;\n    /* or 106% */\n    display: flex;\n    align-items: flex-end;\n    opacity: .6    \n    }\n\n    .block-field-blockuseruserfield-social-links li {\n    float: right;\n    display: inline;\n    margin-right: 2rem;\n    font-size: 32px;\n    line-height: 34px;\n    }\n    .block-field-blockuseruserfield-social-links ul {\n    margin-bottom: 0;\n    }\n    .layout-main-wrapper {\n    margin-top: 4rem;    \n    }\n    .block-views-blockuser-name-on-user-pages-block-1, .block-views-blockuser-name-on-user-pages-block-1 div,     .block-views-blockuser-name-on-user-pages-block-1 h1 {\n    display: inline-flex;\n\n    }\n   .block-views-blockuser-name-on-user-pages-block-1 {\n    margin-bottom: 4rem;\n    }\n    .field--name-field-photo-credit .field__label, .field--name-field-photo-credit .field__item {\n    display: inline;\n    }\n    .block-field-blockuseruserfield-photo-credit {\n    margin-top: -7rem;\n    /* color: white; */\n    z-index: 10;\n    position: absolute;\n    border-radius: 8px;\n    background: #fff;\n    opacity: .4;\n    padding: .5rem;\n    }\n    .field--label-above .field__item {\n    border-radius: none !important;\n    background: none !important;\n    }\n    @media (max-width: 867px) {\n      .block-field-blockuseruserfield-lifespan {\n        display: block;\n        float: none;\n        font-size: 24px;\n      }\n      .block-views-blockuser-name-on-user-pages-block-1 {\n        margin-bottom: 0;\n      }\n      .highlighted img {\n        height: 15rem !important;\n      object-fit: cover;\n      }\n      .block-field-blockuseruserfield-photo-credit {\n        margin-top: -12rem;\n        float: right;\n        right: .25rem;\n        font-size: 7px;\n        padding: .25rem;\n      }\n      .layout-main-wrapper, .main-content {\n        margin-top: 1rem;\n      }\n    }\n}\n\n/* Mixtape page styles */\n\n.node--type-mixtape .main-content {\n  h2 {\n    color: var(--plum);\n    margin-bottom: 3rem;\n  }\n  .block-views-blockmixtage-body-block-1 {\n    padding-bottom: 4rem;\n    margin-bottom: 4rem;\n  }\n  .block-views-blockcontent-type-index-pages-block-15 {\n  border-bottom : 4px dashed rgba(0, 0, 0, 0.4) ;\n  border-top : 4px dashed rgba(0, 0, 0, 0.4) ;\n  padding: 4rem 0;\n  }\n  .main-wrapper .block-views {\n    margin-bottom: 4rem;\n\n  }\n}\n/* Video page styles */\n\n.node--type-video {\n  .media-oembed-content {\n    width: 100%;\n }\n  .field__label {\n    font-family: 'Roboto';\n    font-style: normal;\n    font-weight: 500;\n    font-size: 18px;\n    line-height: 21px;\n    /* or 117% */\n    letter-spacing: 0.1em;\n    text-transform: uppercase;\n    font-stretch: 110;\n    font-variation-settings: 'GRAD' 0, 'slnt' 0, 'XTRA' 468, 'XOPQ' 96, 'YOPQ' 79, 'YTLC' 514, 'YTUC' 712, 'YTAS' 750, 'YTDE' -203, 'YTFI' 738;\n  } \n  a {\n    text-decoration: none;\n  }\n  .block-layout-builder {\n    margin-bottom: 0;\n  }\n  iframe {\n    border-radius: 10px;\n  }\n  .row {\n    --bs-gutter-x: 0;\n  }\n}\n\n/* Lesson plan styles */\n\n.node--type-lesson-plan {\n  p {\n    line-height: 30px;\n    margin-bottom: 2.5rem;\n  }\n  .layout-main p + ul,  {\n    margin-bottom: 2.5rem;\n    margin-top: -2rem;\n  }\n  p strong {\n    font-family: Roboto;\n  }\n  h2 {\n    font-family: 'Roboto';\n    font-style: normal;\n    font-weight: 900;\n    font-size: 18px;\n    line-height: 21px;\n    /* or 117% */\n    letter-spacing: 0.1em;\n    text-transform: uppercase;\n    font-stretch: 110;\n    font-variation-settings: 'GRAD' 0, 'slnt' 0, 'XTRA' 468, 'XOPQ' 96, 'YOPQ' 79, 'YTLC' 514, 'YTUC' 712, 'YTAS' 750, 'YTDE' -203, 'YTFI' 738;\n  }\n}\n\n/* Winner, judge and photo event pages */\n.winner-index table, .winner-table table, .contest-photos table {\n  a, h4, p {\n  text-decoration: none;\n  font-family: 'Roboto';\n  font-style: normal;\n  font-weight: 500;\n  font-size: 18px;\n  line-height: 21px;\n  /* or 117% */\n  letter-spacing: 0.1em;\n  text-transform: uppercase;\n  font-stretch: 110;\n  font-variation-settings: 'GRAD' 0, 'slnt' 0, 'XTRA' 468, 'XOPQ' 96, 'YOPQ' 79, 'YTLC' 514, 'YTUC' 712, 'YTAS' 750, 'YTDE' -203, 'YTFI' 738;\n  }\n  h4 {\n    font-weight: 700;\n  }\n  img {\n    border-radius: 10px;\n  }\n  table {\n    border: none\n  }\n  tr {\n    background: none;\n    vertical-align: top;\n  }\n  td {\n    display: block;\n    width: 100%;\n  }\n\n\n  td:hover img {\n    filter: brightness(1.2);\n    transition: all .4s ease;\n  }\n}\n.winner-table table {\n  @media (min-width: 867px) {\n    td {\n        width: 30%;\n        display: table-cell;\n    }\n  }\n\n}\n.winner-index table, .contest-photos table {\n  @media (min-width: 867px) {\n    td {\n        width: 45%;\n        display: table-cell;\n    }\n  }\n\n}\n.judge-page table {\n h2 a {\n  text-decoration: none;\n }\n img {\n  border-radius: 10px\n }\n a:hover img {\n  filter: brightness(1.2);\n  transition: all .4s ease;\n  \n }\n}\n.main-content {\n  p {\n    margin-bottom: 2rem;\n  }\n\n}",".node-preview-container {\n  background: #d1e8f5;\n  background-image: -webkit-linear-gradient(top, #d1e8f5, #d3e8f4);\n  background-image: linear-gradient(to bottom, #d1e8f5, #d3e8f4);\n  font-family: Arial, sans-serif;\n  box-shadow: 0 1px 3px 1px rgba(0, 0, 0, 0.3333);\n  position: fixed;\n  z-index: 499;\n  width: 100%;\n  padding: 10px;\n}\n.node-preview-backlink {\n  background-color: #419ff1;\n  background: url(/core/misc/icons/000000/chevron-left.svg) left no-repeat, -webkit-linear-gradient(top, #419ff1, #1076d5);\n  background: url(/core/misc/icons/000000/chevron-left.svg) left no-repeat, linear-gradient(to bottom, #419ff1, #1076d5); /* LTR */\n  border: 1px solid #0048c8;\n  border-radius: .4em;\n  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .4);\n  color: #fff;\n  font-size: 0.9em;\n  line-height: normal;\n  margin: 0;\n  padding: 4px 1em 4px 0.6em; /* LTR */\n  text-shadow: 1px 1px 0 rgba(0, 0, 0, 0.5);\n}\n[dir=\"rtl\"] .node-preview-backlink {\n  background: url(/core/misc/icons/000000/chevron-right.svg) right no-repeat, -webkit-linear-gradient(top, #419ff1, #1076d5);\n  background: url(/core/misc/icons/000000/chevron-right.svg) right no-repeat, linear-gradient(to bottom, #419ff1, #1076d5);\n  padding: 4px 0.6em 4px 1em;\n  float: right;\n}\n.node-preview-backlink:focus,\n.node-preview-backlink:hover {\n  background-color: #419cf1;\n  background: url(/core/misc/icons/000000/chevron-left.svg) left no-repeat, -webkit-linear-gradient(top, #59abf3, #2a90ef);\n  background: url(/core/misc/icons/000000/chevron-left.svg) left no-repeat, linear-gradient(to bottom, #59abf3, #2a90ef); /* LTR */\n  border: 1px solid #0048c8;\n  text-decoration: none;\n  color: #fff;\n}\n[dir=\"rtl\"] .node-preview-backlink:focus,\n[dir=\"rtl\"] .node-preview-backlink:hover {\n  background: url(/core/misc/icons/000000/chevron-right.svg) right no-repeat, -webkit-linear-gradient(top, #59abf3, #2a90ef);\n  background: url(/core/misc/icons/000000/chevron-right.svg) right no-repeat, linear-gradient(to bottom, #59abf3, #2a90ef);\n}\n.node-preview-backlink:active {\n  background-color: #0e69be;\n  background: url(/core/misc/icons/000000/chevron-left.svg) left no-repeat, -webkit-linear-gradient(top, #0e69be, #2a93ef);\n  background: url(/core/misc/icons/000000/chevron-left.svg) left no-repeat, linear-gradient(to bottom, #0e69be, #2a93ef); /* LTR */\n  border: 1px solid #0048c8;\n  box-shadow: inset 0 1px 2px rgba(0, 0, 0, .25);\n}\n[dir=\"rtl\"] .node-preview-backlink:active {\n  background: url(/core/misc/icons/000000/chevron-right.svg) right no-repeat, -webkit-linear-gradient(top, #0e69be, #2a93ef);\n  background: url(/core/misc/icons/000000/chevron-right.svg) right no-repeat, linear-gradient(to bottom, #0e69be, #2a93ef);\n}\n.node-preview-backlink::before {\n  content: '';\n  width: 10px;\n  display: inline-block;\n}\n","/**\n * @file\n * Styles for Bootstrap Barrio page.\n */\n\n/* Hack for .placeholder issue https://www.drupal.org/project/drupal/issues/3233533 */\nem.placeholder {\n  vertical-align: unset!important;\n  cursor: unset!important;\n  background-color: unset!important;\n  opacity: unset!important;\n}","/**\n * @file\n * The visual styles for Bootstrap Barrio's search form(s).\n */\n\ninput[type=\"search\"] {\n  box-sizing: border-box;\n}\n\nheader #search-block-form {\n  padding: 5px 15px;\n  flex-flow: row wrap;\n}\n\n#search-block-form {\n  display: flex;\n}\n","/**\n * @file\n * Visual styles for the Shortcut action link in Bootstrap Barrio.\n */\n\n.shortcut-wrapper {\n  margin: 2.2em 0 1.1em 0; /* Same as usual .page-title margin. */\n}\n.shortcut-wrapper .page-title {\n  float: left; /* LTR */\n  margin: 0;\n}\n[dir=\"rtl\"] .shortcut-wrapper .page-title {\n  float: right;\n}\n.shortcut-action {\n  border-bottom: none;\n  margin-left: 0.5em; /* LTR */\n  padding-top: 0.35em;\n}\n[dir=\"rtl\"] .shortcut-action {\n  margin-left: 0;\n  margin-right: 0.5em;\n}\n.shortcut-action:hover,\n.shortcut-action:active,\n.shortcut-action:focus {\n  border-bottom: none;\n}\n","/* ------------------ Sidebar ----------------- */\n\n#sidebar_first {\n  height: 100%;\n  padding-right: 0;\n  padding-top: 20px;\n}\n\n/* collapsed sidebar styles */\n@media (max-width: 47.9em) {\n  .row-offcanvas {\n    position: relative;\n    -webkit-transition: all 0.25s ease-out;\n    -moz-transition: all 0.25s ease-out;\n    transition: all 0.25s ease-out;\n  }\n  .row-offcanvas-right  .sidebar-offcanvas {\n    right: -41.6%;\n  }\n\n  .row-offcanvas-left  .sidebar-offcanvas {\n    left: -41.6%;\n  }\n  .row-offcanvas-right.active {\n    right: 41.6%;\n  }\n  .row-offcanvas-left.active {\n    left: 41.6%;\n  }\n  .sidebar-offcanvas {\n    position: absolute;\n    top: 0;\n    width: 41.6%;\n  }\n  .sidebar_first {\n    padding-top: 0;\n  }\n}\n","/* ------------------ Sidebar ----------------- */\n\n.sidebar  {\n    filter: drop-shadow(0px 0px 10px rgba(0, 0, 0, 0.16));\n    border-radius: 10px;\n    padding: 15px 15px;\n    margin: 0 0 20px;\n    background: #fff;\n    border: none;\n    height: fit-content;\nfont-family: 'Roboto';\n}\n\n.sidebar h2 {\n  margin: 0 0 0.5em;\n    border: none;\n  padding-bottom: 5px;\n  text-shadow: 0 1px 0 #fff;\n  font-size: 1.071em;\n  line-height: 1.2;\n}\n\n.sidebar .block .content, .sidebar .block .content li, \n.sidebar .block .content p {\n  font-size: 0.914em;\n  line-height: 1.4;\nfont-family: 'Roboto';\n}\n\n.sidebar tbody {\n  border: none;\n}\n\n.sidebar .even,\n.sidebar .odd {\n  background: none;\n  border-bottom: 1px solid #d6d6d6;\n}\n\n.sidebar nav .nav {\n  margin: 0 -1rem;\n}\n.gold-dark-bg {\n    background-color: var(--gold-dark); \n    color: #fff;\n    padding: 20px\n}\n\n.dark a {\ncolor: #fff\n}\n\n.dark h2 {\ncolor: #fff;\n\n}\n\n.layout-main {\npadding-right: 10%;\n}\n\n.sidebar .block  {\nborder: none;\nborder-bottom: 1px solid rgba(255, 255, 255, 0.4);\npadding: 0 0 1.2em;\n}\n.sidebar a {\ntext-decoration:none\n}\n.sidebar .block-inline-blockbasic, .sidebar .block-field-blocknodelesson-planfield-learning-objectives {\nborder-bottom: none !important;\n}\n.sidebar .block-inline-blockbasic h3 {\n    font-style: normal;\nfont-weight: 1000;\nfont-size: 18px;\nline-height: 21px;\n/* or 117% */\nletter-spacing: 0.1em;\ntext-transform: uppercase;\nfont-stretch: 110;\nfont-variation-settings: 'GRAD' 0, 'slnt' 0, 'XTRA' 468, 'XOPQ' 96, 'YOPQ' 79, 'YTLC' 514, 'YTUC' 712, 'YTAS' 750, 'YTDE' -203, 'YTFI' 738;\n}\n\n","/**\n * @file\n * Footer Styling.\n */\n\n.site-footer {\n  font-family: \"Helvetica Neue\", Helvetica, Arial, sans-serif;\n  padding: 35px 0 30px;\n}\n.site-footer .layout-container {\n  padding: 0 15px;\n}\n@media all and (min-width: 560px) {\n  .site-footer__top .region {\n    float: left; /* LTR */\n    position: relative;\n    width: 50%;\n  }\n  [dir=\"rtl\"] .site-footer__top .region {\n    float: right;\n  }\n}\n@media all and (min-width: 560px) and (max-width: 850px) {\n  .site-footer .region {\n    box-sizing: border-box;\n  }\n  .site-footer__top .region:nth-child(2n+1) {\n    padding-right: 10px; /* LTR */\n  }\n  [dir=\"rtl\"] .site-footer__top .region:nth-child(2n+1) {\n    padding-left: 10px;\n    padding-right: 0;\n  }\n  .site-footer__top .region:nth-child(2n) {\n    padding-left: 10px; /* LTR */\n  }\n  [dir=\"rtl\"] .site-footer__top .region:nth-child(2n) {\n    padding-left: 0;\n    padding-right: 10px;\n  }\n  .region-footer-third {\n    clear: both;\n  }\n}\n@media all and (min-width: 851px) {\n  .site-footer__top .region {\n    width: 48%;\n    padding: 0 0.65%;\n  }\n  .site-footer__top .region:first-child {\n    padding-left: 0; /* LTR */\n  }\n  [dir=\"rtl\"] .site-footer__top .region:first-child {\n    padding-left: 10px;\n    padding-right: 0;\n  }\n  .site-footer__top .region:last-child {\n    padding-right: 0; /* LTR */\n  }\n  [dir=\"rtl\"] .site-footer__top .region:last-child {\n    padding-left: 0;\n    padding-right: 10px;\n  }\n}\n.site-footer h2 {\n  color: #c0c0c0;\n  color: rgba(255, 255, 255, 0.65);\n}\n.site-footer blockquote {\n  color: #555;\n}\n.site-footer .content {\n  color: #c0c0c0;\n  color: rgba(255, 255, 255, 0.65);\n  font-size: 0.857em;\n}\n.site-footer .menu-item {\n  padding: 0;\n}\n.site-footer .content ol:not(.menu),\n.site-footer .content ul:not(.menu) {\n  padding-left: 1.4em; /* LTR */\n}\n[dir=\"rtl\"] .site-footer .content ol:not(.menu),\n[dir=\"rtl\"] .site-footer .content ul:not(.menu) {\n  padding-right: 1.4em;\n  padding-left: 0;\n}\n.site-footer .content a,\n.site-footer .content a.is-active {\n  color: #fcfcfc;\n  color: rgba(255, 255, 255, 0.8);\n}\n.site-footer .content a:hover,\n.site-footer .content a:focus {\n  color: #fefefe;\n  color: rgba(255, 255, 255, 0.95);\n}\n.site-footer .block {\n  margin: 20px 0;\n  border: none;\n  padding: 10px;\n}\n.site-footer table {\n  font-size: 1em;\n}\n.site-footer tr td,\n.site-footer tr th {\n  border-color: #555;\n  border-color: rgba(255, 255, 255, 0.18);\n}\n.site-footer tr.odd {\n  background-color: transparent;\n}\n.site-footer tr.even {\n  background-color: #2c2c2c;\n  background-color: rgba(0, 0, 0, 0.15);\n}\n\n/* Footer Top Styling. */\n.site-footer__top h2 {\n  border-bottom: 1px solid #555;\n  border-color: rgba(255, 255, 255, 0.15);\n  font-size: 1em;\n  margin-bottom: 0;\n  padding-bottom: 3px;\n  text-transform: uppercase;\n}\n.site-footer__top .content {\n  margin-top: 0;\n}\n.site-footer__top p {\n  margin-top: 1em;\n}\n.site-footer__top .content .menu {\n  padding-left: 0; /* LTR */\n}\n[dir=\"rtl\"] .site-footer__top .content .menu {\n  padding-right: 0;\n}\n.site-footer__top .content li a {\n  display: block;\n  border-bottom: 1px solid #555;\n  border-color: rgba(255, 255, 255, 0.15);\n  line-height: 1.2;\n  padding: 0.8em 2px 0.8em 20px; /* LTR */\n  text-indent: -15px;\n}\n[dir=\"rtl\"] .site-footer__top .content li a {\n  padding: 0.8em 20px 0.8em 2px;\n}\n.site-footer__top .content li a:hover,\n.site-footer__top .content li a:focus {\n  background-color: #1f1f21;\n  background-color: rgba(255, 255, 255, 0.05);\n  text-decoration: none;\n}\n.site-footer__top .block-menu,\n.site-footer__bottom .block {\n  margin: 0;\n  padding: 0;\n  border: none;\n}\n\n/* Footer Bottom Styling. */\n.site-footer__bottom .block {\n  margin: 0.5em 0;\n}\n.site-footer__bottom .content {\n  padding: 0.5em 0;\n  margin-top: 0;\n}\n.site-footer__bottom .block h2 {\n  margin: 0;\n}\n.site-footer__bottom {\n  letter-spacing: 0.2px;\n  margin-top: 30px;\n  border-top: 1px solid #555;\n  border-color: rgba(255, 255, 255, 0.15);\n}\n.site-footer__bottom .region {\n  margin-top: 20px;\n}\n.site-footer__bottom .block {\n  clear: both;\n}\n\n/* We need to be specific to overwrite [dir=\"rtl\"] .block ul in block.css. */\n.site-footer__bottom .block .menu {\n  padding: 0;\n}\n.site-footer__bottom .menu-item a {\n  float: left; /* LTR */\n  padding: 0 12px;\n  display: block;\n  border-right: 1px solid #555; /* LTR */\n  border-color: rgba(255, 255, 255, 0.15);\n}\n[dir=\"rtl\"] .site-footer__bottom .menu-item a {\n  float: right;\n  border-left: 1px solid #555;\n  border-right: none;\n}\n.site-footer__bottom .menu-item:first-child a {\n  padding-left: 0; /* LTR */\n}\n[dir=\"rtl\"] .site-footer__bottom .menu-item:first-child a {\n  padding-right: 0;\n  padding-left: 12px;\n}\n.site-footer__bottom .menu-item:last-child a {\n  padding-right: 0; /* LTR */\n  border-right: none; /* LTR */\n}\n[dir=\"rtl\"] .site-footer__bottom .menu-item:last-child a {\n  padding-left: 0;\n  padding-right: 12px;\n  border-left: none;\n}\n\n/**\n * When the item is both first and last, :last-child overrides the right padding\n * when using [dir=\"rtl\"]. We need this rule to remove the right padding.\n */\n[dir=\"rtl\"] .site-footer__bottom .menu-item:first-child:last-child a {\n  padding-right: 0;\n}\n.site-footer li a  {\ncolor: #fff;\n}\n.site-footer {\n    padding:0 !important;\n    background-size: cover;\n}\n.site-footer .container {\n    background: rgba(0, 0, 0, 0.3);   \n    border-radius: 1rem; \n}\n\n.site-footer .footer-blur {\n    background: rgba(0, 0, 0, 0.3);    \n    backdrop-filter: blur(50px);\n    padding: 4rem 0rem;\n\n}\n.site-footer .container {\n    padding: 3rem;\n}\n.footer .navbar-nav {\ndisplay: block;\n}\n.footer .navbar-nav li {\ndisplay: block;\nfloat: none;\n}\n\n","/**\n * @file\n * Styles for the skip link.\n */\n\n.skip-link {\n  left: 50%;\n  -webkit-transform: translateX(-50%);\n  -ms-transform: translateX(-50%);\n  transform: translateX(-50%);\n  z-index: 50;\n  background: #444;\n  background: rgba(0, 0, 0, 0.6);\n  font-size: 0.94em;\n  line-height: 1.7em;\n  padding: 1px 10px 2px;\n  border-radius: 0 0 10px 10px;\n  border-bottom-width: 0;\n  outline: 0;\n}\n.skip-link.visually-hidden.focusable:focus {\n  position: absolute !important;\n  color: #fff;\n}\n","/**\n * @file\n * Detailed stylings are all yours, get yourself dirty.\n *\n * Transform is more performed than positions.\n */\n\n.slick--skin--classic .slick__slide {\n  overflow: hidden;\n}\n\n.slick--skin--classic .slide__caption {\n  box-sizing: border-box; /* dups due to csslint ignoring inheritance */\n  background-color: #000;\n  background-color: rgba(0, 0, 0, 0.8);\n  color: #fff;\n  left: auto;\n  margin: 0;\n  min-height: 80px;\n  padding: 15px;\n  -webkit-transition: -webkit-transform 1s ease-in-out 0.2s;\n  transition: transform 1s ease-in-out 0.2s;\n  width: 100%;\n}\n\n.slick--skin--classic .slide__description {\n  margin: 0;\n}\n\n.slick--skin--classic .slide--caption--below .slide__caption {\n  background: none;\n  color: #38465c;\n}\n\n.slick--skin--classic .slide--caption--center .slide__caption {\n  color: #fff;\n  opacity: 0;\n  visibility: hidden;\n  -webkit-transition: all 0.4s ease-in-out 0s;\n  transition: all 0.4s ease-in-out 0s;\n  -webkit-backface-visibility: hidden;\n}\n\n.slick--skin--classic .slide--caption--center:hover .slide__caption {\n  opacity: 1;\n  visibility: visible;\n}\n\n@media (min-width: 64em) {\n  .slick--skin--classic .slide__caption {\n    box-sizing: border-box; /* dups due to csslint ignoring inheritance */\n    height: 100%;\n    min-height: 100%;\n    padding: 60px 30px;\n    top: 0;\n    width: 22%;\n  }\n\n  .slick--skin--classic .slide__caption .slide__data {\n    box-sizing: border-box; /* dups due to csslint ignoring inheritance */\n    margin: 0 !important; /* csslint allow: known-properties, important */\n    padding: 15px;\n    width: 100%;\n  }\n\n  .slick--skin--classic .slide--caption--center .slide__caption {\n    height: 120px;\n    left: 50%;\n    margin: -60px 0 0 -40%;\n    min-height: 120px;\n    top: 50%;\n    width: 80%;\n  }\n\n  .slick--skin--classic .slide--caption--top .slide__caption,\n  .slick--skin--classic .slide--caption--center-top .slide__caption,\n  .slick--skin--classic .slide--caption--bottom .slide__caption,\n  .slick--skin--classic .slide--caption--below .slide__caption {\n    box-sizing: border-box; /* dups due to csslint ignoring inheritance */\n    height: auto;\n    min-height: 80px;\n    padding: 30px;\n    width: 100%;\n  }\n\n  .slick--skin--classic .slide--caption--bottom .slide__caption {\n    bottom: 0;\n    -ms-transform: translateY(210px);\n    -webkit-transform: translateY(210px);\n    transform: translateY(210px);\n    min-height: 120px;\n    top: auto;\n  }\n\n  .slick--skin--classic .slide--caption--stage-zebra .slide__title {\n    margin-bottom: 30px;\n  }\n\n  .slick--skin--classic .slide--caption--stage-zebra:nth-child(odd) .slide__caption,\n  .slick--skin--classic .slide--caption--stage-left .slide__caption,\n  .slick--skin--classic .slide--caption--left .slide__caption {\n    left: 0;\n    -ms-transform: translateX(-320px);\n    -webkit-transform: translateX(-320px);\n    transform: translateX(-320px);\n  }\n\n  .slick--skin--classic .slide--caption--stage-zebra:nth-child(even) .slide__caption,\n  .slick--skin--classic .slide--caption--stage-right .slide__caption,\n  .slick--skin--classic .slide--caption--right .slide__caption {\n    left: auto;\n    right: 0;\n    -ms-transform: translateX(320px);\n    -webkit-transform: translateX(320px);\n    transform: translateX(320px);\n  }\n\n  .slick--skin--classic .slide--caption--top .slide__caption,\n  .slick--skin--classic .slide--caption--center-top .slide__caption {\n    top: 0;\n    -ms-transform: translateY(-210px);\n    -webkit-transform: translateY(-210px);\n    transform: translateY(-210px);\n  }\n\n  .slick--skin--classic .slick__slide.slick-active .slide__caption {\n    -ms-transform: translateY(0);\n    -webkit-transform: translateY(0);\n    transform: translateY(0);\n    -webkit-transition-delay: 0s;\n    transition-delay: 0s;\n  }\n}\n.slick__slide {\n\n\n}\n .slick-initialized .slick__slide {\n\nmargin: 0px 30px\n}\n.slick__slide h3 {\npadding: 1em;\n}\n\n","@media (max-width: 767px) {\n  .navbar-collapse {\n    border-top: 0;\n  }\n  .navbar-collapse .navbar-nav {\n    margin-right: 0;\n    margin-left: 0;\n  }\n  .navbar-collapse [class*=\"container\"] {\n    background-color: inherit;\n    border-color: inherit;\n  }\n  .navbar-collapse .navigation {\n    position: fixed;\n    top: 0;\n    bottom: 0;\n    left: 0;\n    z-index: 1030;\n    width: 240px;\n    height: 100%;\n    margin: 0;\n    overflow: auto;\n    background-color: white;\n    border-right: 1px solid;\n    border-right-color: inherit;\n    padding-left: 0.25rem;\n  }\n  .bg-dark .navbar-collapse .navigation {\n    background-color: #17141f !important;\n  }\n  .navbar-collapse .navigation .navbar-nav .dropdown-menu li a {\n    width: 100%;\n    white-space: normal;\n  }\n  .navbar-collapse .navbar-form {\n    width: 100%;\n    margin: 8px 0;\n    overflow: hidden;\n    text-align: center;\n  }\n}\n@media (min-width: 768px) {\n  .navigation {\n    display: block;\n    width: auto !important;\n\n  }\n}\n\n.navbar-dark .navbar-toggler-icon {\n  opacity: 0.6;\n  background-size: 60%;\n  background-image: url(\"data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' fill='%23000'%3e%3cpath d='M.293.293a1 1 0 011.414 0L8 6.586 14.293.293a1 1 0 111.414 1.414L9.414 8l6.293 6.293a1 1 0 01-1.414 1.414L8 9.414l-6.293 6.293a1 1 0 01-1.414-1.414L6.586 8 .293 1.707a1 1 0 010-1.414z'/%3e%3c/svg%3e\");\n}\n\n.navbar-dark .collapsed .navbar-toggler-icon {\n  background-image: url(\"data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' width='30' height='30' viewBox='0 0 30 30'%3e%3cpath stroke='rgba%28255, 255, 255, 0.5%29' stroke-linecap='round' stroke-miterlimit='10' stroke-width='2' d='M4 7h22M4 15h22M4 23h22'/%3e%3c/svg%3e\");\n}\n\n.navbar-light .navbar-toggler-icon {\n  opacity: 0.6;\n  background-size: 60%;\n  background-image: url(\"data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' fill='%23000'%3e%3cpath d='M.293.293a1 1 0 011.414 0L8 6.586 14.293.293a1 1 0 111.414 1.414L9.414 8l6.293 6.293a1 1 0 01-1.414 1.414L8 9.414l-6.293 6.293a1 1 0 01-1.414-1.414L6.586 8 .293 1.707a1 1 0 010-1.414z'/%3e%3c/svg%3e\");\n}\n\n.navbar-light .collapsed .navbar-toggler-icon {\n  background-image: url(\"data:image/svg+xml,%3csvg xmlns='http://www.w3.org/2000/svg' width='30' height='30' viewBox='0 0 30 30'%3e%3cpath stroke='rgba%280, 0, 0, 0.4%29' stroke-linecap='round' stroke-miterlimit='10' stroke-width='2' d='M4 7h22M4 15h22M4 23h22'/%3e%3c/svg%3e\");\n}\n","/**\n * @file\n * Visual styles for table drag.\n */\n\ntr.drag {\n  background-color: #fffff0;\n}\ntr.drag-previous {\n  background-color: #ffd;\n}\nbody div.tabledrag-changed-warning {\n  margin-bottom: 0.5em;\n}\n","/**\n * @file\n * Styles for Bootstrap Barrio's tables.\n */\n\ntable {\n  border: 0;\n  border-spacing: 0;\n  font-size: 0.857em;\n  margin: 10px 0;\n  width: 100%;\n}\ntable table {\n  font-size: 1em;\n}\ntr {\n  border-bottom: 1px solid #ccc;\n  padding: 0.1em 0.6em;\n  background: #efefef;\n  background: rgba(0, 0, 0, 0.063);\n}\nthead > tr {\n  border-bottom: 1px solid #000;\n}\ntr.odd {\n  background: #e4e4e4;\n  background: rgba(0, 0, 0, 0.105);\n}\ntable tr th {\n  background: #757575;\n  background: rgba(0, 0, 0, 0.51);\n  border-bottom-style: none;\n}\ntable tr th,\ntable tr th a,\ntable tr th a:hover,\ntable tr th a:focus {\n  color: #fff;\n  font-weight: bold;\n}\ntable tbody tr th {\n  vertical-align: top;\n}\ntr td,\ntr th {\n  padding: 4px 9px;\n  border: 1px solid #fff;\n  text-align: left; /* LTR */\n}\n[dir=\"rtl\"] tr td,\n[dir=\"rtl\"] tr th {\n  text-align: right;\n}\n\n/**\n * Responsive tables.\n */\n@media screen and (max-width: 37.5em) { /* 600px */\n  th.priority-low,\n  td.priority-low,\n  th.priority-medium,\n  td.priority-medium {\n    display: none;\n  }\n}\n@media screen and (max-width: 60em) { /* 920px */\n  th.priority-low,\n  td.priority-low {\n    display: none;\n  }\n}\n","/**\n * @file\n * Table select behavior.\n *\n * @see tableselect.js\n */\n\ntr.selected td {\n  background: #ffc;\n}\ntd.checkbox,\nth.checkbox {\n  text-align: center;\n}\n[dir=\"rtl\"] td.checkbox,\n[dir=\"rtl\"] th.checkbox {\n  /* This is required to win over specificity of [dir=\"rtl\"] td */\n  text-align: center;\n}\n","/**\n * @file\n * Tablesort indicator styles.\n */\n\n.tablesort {\n  width: 14px;\n  height: 14px;\n  vertical-align: top;\n  margin: 1px 0 0 5px;\n}\n\n.tablesort--asc {\n  background-image: url(/core/misc/icons/ffffff/twistie-down.svg);\n}\n\n.tablesort--desc {\n  background-image: url(/core/misc/icons/ffffff/twistie-up.svg);\n}\n","/**\n * @file\n * Table sort indicator.\n */\n\nth.is-active img {\n  display: inline;\n}\ntd.is-active {\n  background-color: #ddd;\n}\n","/**\n * @file\n * Theme styling for tabs.\n */\n\nnav.tabs {\n  margin-bottom: 1rem;\n}\n\nnav.tabs ul {\n  background: #e9ecef;\n  display: -webkit-box;\n  display: -webkit-flex;\n  display: -ms-flexbox;\n  display: flex; \n}\nnav.tabs ul .nav-item {\n  flex-grow: 1; \n}\nnav.tabs ul .nav-item a {\n  color: #303030;\n  text-align: center;\n}\nnav.tabs ul .nav-item.active a {\n  background: #303030;\n  color: #e9ecef;\n}\n","/**\n * @file\n * Theme styling for tabs.\n */\n\nnav.tabs {\n  margin-bottom: 1rem;\n}\n","/**\n * @file\n * Visual styles for a resizable textarea.\n */\n\n.form-textarea-wrapper textarea {\n  display: block;\n  margin: 0;\n  width: 100%;\n  box-sizing: border-box;\n}\n","body.toolbar-horizontal #navbar-top.fixed-top,\nbody.toolbar-vertical #navbar-top.fixed-top,\nbody.toolbar-vertical.toolbar-tray-open #navbar-top.fixed-top,\nbody.toolbar-horizontal #navbar-main.fixed-top,\nbody.toolbar-vertical #navbar-main.fixed-top,\nbody.toolbar-vertical.toolbar-tray-open #navbar-main.fixed-top {\n  top: 40px;\n}\nbody.toolbar-horizontal.toolbar-tray-open #navbar-top.fixed-top,\nbody.toolbar-horizontal.toolbar-tray-open #navbar-main.fixed-top {\n  top: 80px;\n}\nbody.toolbar-fixed .toolbar-oriented .toolbar-bar {\n  z-index: 1040;\n}\n","/**\n * @file\n * Styles for Bartik's modal windows\n */\n\n.ui-widget-overlay {\n  background: #000;\n  opacity: 0.7;\n}\n.ui-dialog {\n  font-family: \"Helvetica Neue\", Helvetica, Arial, sans-serif;\n  border-radius: 0;\n}\n.ui-dialog input,\n.ui-dialog select,\n.ui-dialog textarea {\n  font-size: 0.9em;\n}\n.ui-dialog .button {\n  background-color: #fff;\n  background-image: -webkit-linear-gradient(top,#f3f3f3,#e8e8e8);\n  background-image: linear-gradient(to bottom,#f3f3f3,#e8e8e8);\n  border: 1px solid #e4e4e4;\n  border-bottom-color: #b4b4b4;\n  border-left-color: #d2d2d2;\n  border-right-color: #d2d2d2;\n  color: #3a3a3a;\n  cursor: pointer;\n  font-size: 0.929em;\n  font-weight: normal;\n  text-align: center;\n  padding: 0.250em 1.063em;\n  border-radius: 1em;\n}\n","/**\n * @file\n * Visual styles for Bartik's ui-widget component.\n */\n\n#page .ui-widget {\n  font-family: \"Helvetica Neue\", Helvetica, Arial, sans-serif;\n}\n","/**\n * @file\n * Theme styling for user module.\n */\n\n/* Visual styling for the Password strength indicator */\n.password-strength__meter {\n  margin-top: 0.5em;\n  background-color: #ebeae4;\n}\n.password-strength__indicator {\n  background-color: #77b259;\n  -webkit-transition: width 0.5s ease-out;\n  transition: width 0.5s ease-out;\n}\n.password-strength__indicator.is-weak {\n  background-color: #e62600;\n}\n.password-strength__indicator.is-fair {\n  background-color: #e09600;\n}\n.password-strength__indicator.is-good {\n  background-color: #0074bd;\n}\n.password-strength__indicator.is-strong {\n  background-color: #77b259;\n}\n\n.password-confirm,\n.password-field,\n.password-strength,\n.password-confirm-match {\n  width: 55%;\n}\n\n.password-suggestions {\n  padding: 0.2em 0.5em;\n  margin: 0.7em 0;\n  max-width: 34.7em;\n  border: 1px solid #b4b4b4;\n}\n.password-suggestions ul {\n  margin-bottom: 0;\n}\n\n.confirm-parent,\n.password-parent {\n  clear: left; /* LTR */\n  margin: 0;\n  max-width: 33em;\n  overflow: hidden;\n}\n[dir=\"rtl\"] .confirm-parent,\n[dir=\"rtl\"] .password-parent {\n  clear: right;\n}\n\n/* Styling for the status indicator of the passwords match test.  */\n.password-confirm .ok {\n  color: #325e1c;\n  font-weight: bold;\n}\n.password-confirm .error {\n  color: #a51b00;\n  font-weight: bold;\n}\n\n/* Login page stype */\n.page-user-login main .region-content,\n.page-user-password main .region-content {\n  max-width: 400px;\n  background: white;\n  padding: 15px 25px;\n  margin: 0 auto;\n  border-radius: 5px;\n}\n\n/* User account page */\nbody.path-user .field--label-inline .field__label {\n  width: 100px;\n}\n\nbody.path-user .field--label-inline .field__item {\n  padding: 0.25rem 1rem;\n  border-radius: none;\n  background: #fff;\n  min-width: 250px;\n  margin: 0.25rem 0;\n}\n\nbody.path-user .field--label-above .field__item {\n  padding: 0.25rem 1rem;\n  border-radius: none;\n  background: #fff;\n  width: 100%;\n  margin: 0.25rem 0;\n}\n","/**\n * @file\n * Vertical tabs component.\n */\n\n/* Vertical Tabs Reset */\n.vertical-tabs__menu {\n  margin: -1px 0 -1px; /* LTR */\n  padding: 0;\n}\n[dir=\"rtl\"] .vertical-tabs__menu {\n  margin-left: 0;\n  margin-right: -1em;\n  /* This is required to win specificity over [dir=\"rtl\"] .region-content ul */\n  padding: 0;\n}\n","/**\n * @file\n * Vertical Tabs.\n */\n\n.vertical-tabs {\n  margin: 0;\n  /* LTR */\n  border: 1px solid #ccc;\n  display: flex;\n  flex-direction: row;\n  font-size: 0.875rem;\n}\n\n[dir=\"rtl\"] .vertical-tabs {\n  flex-direction: row-reverse;\n  margin-left: 0;\n  margin-right: 0;\n}\n\n.vertical-tabs__menu {\n  display: flex;\n  flex-direction: column;\n  flex-wrap: nowrap;\n  /* LTR */\n  width: 15em;\n  margin: 0;\n  /* LTR */\n  padding: 0;\n  border-top: 1px solid #ccc;\n  list-style: none;\n}\n\n[dir=\"rtl\"] .vertical-tabs__menu {\n  margin-left: 0;\n  margin-right: -15em;\n}\n\n.vertical-tabs__pane {\n  margin: 0;\n  border: 0;\n}\n\n.vertical-tabs__pane>summary {\n  display: none;\n}\n\n\n/* Layout of each tab. */\n\n.vertical-tabs__menu-item {\n  border: 1px solid #ccc;\n  border-top: 0;\n  background: #eee;\n}\n\n.vertical-tabs__menu-item a {\n  display: block;\n  padding: 0.5em 0.6em;\n  text-decoration: none;\n}\n\n.vertical-tabs__menu-item a:focus .vertical-tabs__menu-item-title,\n.vertical-tabs__menu-item a:active .vertical-tabs__menu-item-title,\n.vertical-tabs__menu-item a:hover .vertical-tabs__menu-item-title {\n  text-decoration: underline;\n}\n\n.vertical-tabs__menu-item a:hover {\n  outline: 1px dotted;\n}\n\n.vertical-tabs__menu-item.is-selected {\n  border-right-width: 0;\n  /* LTR */\n  background-color: #fff;\n}\n\n[dir=\"rtl\"] .vertical-tabs__menu-item.is-selected {\n  border-left-width: 0;\n  border-right-width: 1px;\n}\n\n.vertical-tabs__menu-item.is-selected .vertical-tabs__menu-item-title {\n  color: #000;\n}\n\n.vertical-tabs__menu-item-summary {\n  display: block;\n  margin-bottom: 0;\n  line-height: normal;\n}\n","/**\n * @file\n * Styling for Views in Bartik.\n */\n\n/* Tab styles */\n.views-displays .tabs .open > a {\n  border-radius: 7px 7px 0 0;\n}\n.views-displays .tabs .open > a:hover,\n.views-displays .tabs .open > a:focus {\n  color: #0071b3;\n}\n.views-displays .secondary .form-submit {\n  font-size: 0.846em;\n}\n\n/* Tabs action list styles */\n.views-displays .tabs .action-list {\n  padding: 0;\n}\n\n/* Contextual filter options styles */\n.views-filterable-options .filterable-option:nth-of-type(even) .form-type-checkbox {\n  background-color: #f9f9f9;\n}\n\n/* Views action dropbutton styles */\n.views-ui-display-tab-actions .dropbutton .form-submit {\n  color: #0071b3;\n}\n.views-ui-display-tab-actions .dropbutton .form-submit:hover,\n.views-ui-display-tab-actions .dropbutton .form-submit:focus {\n  color: #018fe2;\n}\n\n\n","#welcome-modal {\n  width: 100vw;\n  height: 100vh;\n  z-index: 30000;\n  position: fixed;\n  top: 0;\n  left: 0;\n  border: 0;\n  background: #F1EDEC;\n  &::backdrop {\n    background-color: #F1EDEC;\n  }\n  .welcome-modal-inner {\n    margin-top: 3rem;\n  }\n  .start-here, .welcome-modal-back {\n    font-size: 2rem;\n    font-weight: 400;\n    line-height: 2rem;\n    font-family: 'Roboto Condensed';\n  }\n  .welcome-modal-back {\n    display: block;\n    margin-bottom: 70px;\n    &:hover {\n      color: #000;\n    }\n  }\n  .close-welcome-modal {\n    right: 0;\n    top: 1rem;\n    position: absolute;\n    cursor: pointer;\n    font-size: 1.25rem;\n  }\n  form {\n    font-family: Roboto;\n    line-height: 100%;\n    font-weight: 900;\n    .form-required::after {\n      display: none;\n    }\n    .options-wrapper {\n      display: flex;\n      margin-top: 70px;\n    }\n  }\n  .piv-select-placeholder {\n    border-bottom: 3px solid;\n    height: 2rem;\n  }\n  .form-item-option-3 .piv-select {\n    margin: 0 10px 0 0;\n  }\n  .piv-select {\n    display: inline-block;\n    vertical-align: top;\n    margin: 0 10px;\n  }\n  .piv-select-options {\n    text-transform: uppercase;\n    font-size: 1rem;\n    color: #918E8D;\n    line-height: 1.5rem;\n    margin-top: 15px;\n  }\n  .piv-select-options.hide {\n    display: none;\n  }\n  fieldset {\n    padding-top: 0;\n    opacity: 1;\n    transition: opacity 0.5s, padding-top 0.5s;\n    width: auto;\n    height: auto;\n    font-size: 0;\n    > * {\n      font-size: 2.5rem;\n    }\n    &.select-hidden {\n      padding-top: 50px;\n      opacity: 0;\n      transition: opacity 0, padding-top 0;\n      width: 0;\n      overflow: hidden;\n      font-size: 0;\n      height: 0;\n    }\n  }\n  #edit-go.form-submit {\n    opacity: 1;\n    transition: opacity 0.5s;\n    background-color: #C53D27;\n    border: 0;\n    color: #fff;\n    text-transform: uppercase;\n    font-weight: 900;\n    width: 160px;\n    height: 70px;\n    margin-top: 40px;\n    &::before {\n      display: none;\n    }\n    &.select-hidden {\n      opacity: 0;\n      transition: opacity 0;\n    }\n  }\n  .menu--account {\n    float: right;\n    margin-right: 30px;\n    margin-top: 2px;\n    a {\n      padding: 0;\n      color: #000;\n    }\n  }\n}\n","/**\n * @file\n * Subtheme specific CSS.\n */\n\n@import \"components/affix\";\n@import \"components/alerts\";\n@import \"components/book\";\n@import \"components/book-navigation\";\n@import \"components/bootstrap-icons\";\n@import \"components/breadcrumb\";\n@import \"components/comments\";\n@import \"components/commerce\";\n@import \"components/contextual\";\n@import \"components/details\";\n@import \"components/dropbutton-component\";\n@import \"components/dropbutton\";\n@import \"components/feed-icon\";\n@import \"components/field\";\n@import \"components/file\";\n@import \"components/form\";\n@import \"components/forum\";\n@import \"components/grid\";\n@import \"components/header\";\n@import \"components/help\";\n@import \"components/home-and-index\";\n@import \"components/icons\";\n@import \"components/image-button\";\n@import \"components/image-widget\";\n@import \"components/img-fluid\";\n@import \"components/indented\";\n@import \"components/item-list\";\n@import \"components/list-group\";\n@import \"components/navigation\";\n@import \"components/node\";\n@import \"components/node-preview\";\n@import \"components/page\";\n@import \"components/progress\";\n@import \"components/search-form\";\n@import \"components/shortcut\";\n@import \"components/sidebar-collapse\";\n@import \"components/sidebar\";\n@import \"components/site-footer\";\n@import \"components/skip-link\";\n@import \"components/slick\";\n@import \"components/slide-nav\";\n@import \"components/tabledrag\";\n@import \"components/table\";\n@import \"components/tableselect\";\n@import \"components/tablesort-indicator\";\n@import \"components/tablesort\";\n@import \"components/tabs-full\";\n@import \"components/tabs\";\n@import \"components/textarea\";\n@import \"components/toolbar\";\n@import \"components/ui-dialog\";\n@import \"components/ui-widget\";\n@import \"components/user\";\n@import \"components/vertical-tabs-component\";\n@import \"components/vertical-tabs\";\n@import \"components/views\";\n@import \"components/welcome-modal\";\n\n:root {\n  --plum-light: #E7D8E3;\n  --plum: #893B73;\n  --plum-dark: #481139;\n  --red-light: #F3D8D4;\n  --red: #C53D27;\n  --red-dark: #631F14;\n  --gold-light: #F4E9DA;\n  --gold: #CA8F47;\n  --gold-dark: #724713;\n  --mint-light: #D4ECE3;\n  --mint: #299F75;\n  --mint-dark: #165740;\n  --aqua-light: #D6E7EF;\n  --aqua: #3185AF;\n  --aqua-dark: #12445E;\n  --white: #ffffff;\n  --grey-dark: #333B42;\n  --grey: #73818D;\n  --black: #000000;\n}\n\n\n\nbody,\nh1,\nh2,\nh3,\nh4,\nh5,\nh6,\nh2 a,\nh3 a, {\n  color: #000;\n  font-family: 'Roboto';\n  word-break: break-word;\n}\n\nh1 {\n  font-family: 'Roboto';\n  font-size: 45px;\n  font-weight: 700;\n  line-height: 47px;\n  text-align: left;\n  font-style:normal;\n}\nh1.light {\n    font-weight: 400;\n    line-height: 44px;\n\n}\nh2 {\n  font-family: 'Roboto';\n  font-style: normal;\n  font-weight: 400;\n  font-size: 32px;\n  line-height: 34px;\n  /* or 106% */\n  font-stretch: 70;\n  font-variation-settings: 'GRAD' 0, 'slnt' 0, 'XTRA' 468, 'XOPQ' 96, 'YOPQ' 79, 'YTLC' 514, 'YTUC' 712, 'YTAS' 750, 'YTDE' -203, 'YTFI' 738;\n}\n\nh3, .navbar-nav .nav-link, .block-views-exposed-filter-blocksearch-page h2 {\n  font-family: 'Roboto';\n  font-style: normal;\n  font-weight: 900;\n  font-size: 18px;\n  line-height: 21px;\n  /* or 117% */\n  letter-spacing: 0.1em;\n  text-transform: uppercase;\n  font-stretch: 110;\n  font-variation-settings: 'GRAD' 0, 'slnt' 0, 'XTRA' 468, 'XOPQ' 96, 'YOPQ' 79, 'YTLC' 514, 'YTUC' 712, 'YTAS' 750, 'YTDE' -203, 'YTFI' 738;\n}\n.navbar-nav .nav-link {\n\n    font-weight: 1000;\n}\nh4, .print__wrapper--pdf a, .site-footer ul li.nav-item a  {\n  font-family: 'Roboto';\n  font-style: normal;\n  font-weight: 500;\n  font-size: 18px;\n  line-height: 21px;\n  /* or 117% */\n  letter-spacing: 0.1em;\n  text-transform: uppercase;\n  font-stretch: 110;\n  font-variation-settings: 'GRAD' 0, 'slnt' 0, 'XTRA' 468, 'XOPQ' 96, 'YOPQ' 79, 'YTLC' 514, 'YTUC' 712, 'YTAS' 750, 'YTDE' -203, 'YTFI' 738;\n}\nh5 {\n\n}\n/* Only for mobile */\n@media (max-width: 867px) {\n\nh1 {\nfont-size: 30px;\n}\nh1.hero {\nfont-size: 24px;\n}\n\nh2 {\nfont-size: 24px;\n}\n\nh3 {\nfont-size: 18px\n}\n\nh4 {\nfont-size: 14px\n}\np, .serif-large {\n  font-family: 'Lora';\n  font-style: normal;\n  font-weight: 400;\n  font-size: 17px;\n  line-height: 36px;\n  /* or 180% */\n}\n.no-blur img {\n    width: 100%;\n    height: 15rem !important;\n    object-fit: cover\n}\n}\n\n\na {\n  color: #000\n}\np, .serif-large {\n  font-family: 'Lora';\n  font-style: normal;\n  font-weight: 400;\n  font-size: 20px;\n  line-height: 36px;\n  /* or 180% */\n}\n.block-field-blocknodepoembody p {\n    font-size: 20px;\n}\n.serif {\n  font-family: 'Lora';\n  font-style: normal;\n\n  font-weight: 400;\n  font-size: 17px;\n  line-height: 30px;\n  /* or 176% */\n}\n.sans-serif {\n  font-family: 'Roboto';\n  font-style: normal;\n  font-weight: 400;\n  font-size: 17px;\n  line-height: 30px;\n  color: #000000;\n}\n.white {\n  color: #fff;\n}\n\n\n\nli {\nfont-family: Roboto;\nfont-size: 17px;\nfont-weight: 400;\nline-height: 30px;\nletter-spacing: 0em;\ntext-align: left;\n}\n.block-field-blocknodelesson-planfield-lesson-objectives, .block-field-blocknodelesson-planfield-materials-resources {\n  filter: drop-shadow(0px 0px 10px rgba(0, 0, 0, 0.16));\n  border-radius: 6px;\n  background: #fff;\n  padding: 20px !important;\n}\n\n.block-layout-builder {\nmargin-bottom: 40px;\n}\n\n\n.field--type-entity-reference {\n    margi