portant;\n\n}\n.md-bg {\nh1, h2, h3, h4, h5, h6, p, a, li {\ncolor: white;\n}\n}\n.dk-bg {\nh1, h2, h3, h4, h5, h6, p, a, li {\ncolor: white ;\n}\n}\n.lt-bg {\nh1, h2, h3, h4, h5, h6, p, a, li {\ncolor: black ;\n}\n}\n.read, .lire {\n    .lt-bg {\n            background: var(--plum-light);\n    }\n\n    .md-bg {\n            background: var(--plum);\n    }\n    .dk-bg {\n            background: var(--plum-dark);\n    }\n    .area-link:hover .content  {\n            background: var(--plum-light);\n            color: var(--plum-dark);\n            height: 100%;\n            transition: all .4s ease;\n            h1, h2, h3, h4, h5, h6, p, li, a {\n                color: var(--plum-dark); \n                transition: all .4s ease;                   \n                }\n        \n    }\n    .block-views-blockcontent-type-index-pages-block-3 .area-link:hover .content  {\n            background: none;\n            color: var(--plum-dark);\n            height: 100%;\n            transition: all .4s ease;\n            h1, h2, h3, h4, h5, h6, p, li, a {\n                color: var(--plum-dark); \n                transition: all .4s ease;                   \n                }\n        \n    }\n    .block-views-blockcontent-type-index-pages-block-3 .area-link:hover .content-index  {\n            background: var(--plum-light);\n            color: var(--plum-dark);\n            height: 100%;\n            transition: all .4s ease;\n            h1, h2, h3, h4, h5, h6, p, li, a {\n                color: var(--plum-dark); \n                transition: all .4s ease;                   \n                }\n        \n    }\n    .view .more-link {\n        background-color: var(--plum-dark);\n    }\n    .hero a {\n        background-color: var(--plum);\n     }\n     .button {\n        background: var(--plum);\n        }\n        details, select {\n            background-color: var(--plum-dark);\n            color: white;\n        }\n}\n.recite, .reciter {\n    .lt-bg {\n            background: var(--red-light);\n    }\n\n    .md-bg {\n            background: var(--red);\n    }\n    .dk-bg {\n            background: var(--red-dark);\n    }\n    .area-link:hover .content {\n            background: var(--red-light);\n            color: black;\n            height: 100%;\n            transition: all .4s ease;\n        h1, h2 h3, h4, h5, h6, p, li, a {\n                color: black !important; \n            transition: all .4s ease;                   \n                }\n        \n    }\n    .view .more-link {\n        background-color: var(--red-dark);\n    }\n    .hero  a {\n        background-color: var(--red);\n     }\n     .button {\n        background: var(--red);\n        }\n        details, select {\n            background-color: var(--red-dark);\n            color: white;\n        }\n}\n.write, .ecrire {\n    .lt-bg { \n            background: var(--mint-light);\n    }\n\n    .md-bg {\n            background: var(--mint);\n    }\n    .dk-bg {\n            background: var(--mint-dark);\n    }\n    .area-link:hover .content {\n            background: var(--mint-light);\n            color: black;\n            height: 100%;\n            transition: all .4s ease;\n        h1, h2 h3, h4, h5, h6, p, li, a {\n                color: black !important; \n            transition: all .4s ease;                   \n                }\n        \n    }\n    .view .more-link {\n        background-color: var(--mint-dark);\n    }\n    .hero a {\n        background-color: var(--mint);\n     }\n     .button {\n        background: var(--mint);\n        }\n    details, select {\n            background-color: var(--mint-dark);\n            color: white;\n     }\n}\n.teach, .enseigner {\n    .lt-bg {\n            background: var(--gold-light);\n    }\n\n    .md-bg {\n            background: var(--gold);\n    }\n    .dk-bg {\n            background: var(--gold-dark);\n    }\n    .area-link:hover  {\n            background: var(--gold-light);\n            color: black;\n  