er: none;\n    border-radius: 0.25rem;\n}\n.offcanvas-body .navbar-toggler,.offcanvas-body #block-usericonheader,.offcanvas-body .language-switcher-language-url {\npadding: 0;\n    font-size: 1rem;\n    line-height: 1;\n    background-color: transparent;\n    border: none;\n    border-radius: none;\n\n}\n.offcanvas-body .btn-close {\n    font-size: 1.25rem; \n}\n.navbar-toggler:focus {\n    box-shadow: none;\n}\n.dropdown-item:focus, .dropdown-item:hover {\n    color: #000;\n    background-color: transparent;\n}\n\n.navbar>.container {\n\n}\n\n.navbar-collapse .user {\nfloat: right;\n}\n\n","/**\n * @file\n * Styles for the help block.\n */\n\n.block-help {\n  border: 1px solid #d3d7d9;\n  padding: 0 1.5em;\n  margin-bottom: 30px;\n}\n","/**\n * @file\n * Subtheme specific CSS.\n */\n\n.block-layout-builder .plum-bg.roulette-discover.col-2-sidebar {\nbackground: var(--plum);\ncolor: white;\n}\n\n.index-subject-row {\n    margin-bottom: 6rem;\n    position: relative;\n\n}\n.view {\n    position: relative\n}\n\n.view .more-link {\n    position: absolute;\n    top: 0;\n    right: 0;\n    border-radius: 6px;\n    padding: .5rem;\n    color: #fff;\n}\n.view .more-link a {\n    color: white;\n    text-decoration: none;\n}\n/* discover poems index page */\n.page-node-27461 {\n    .plum-bg.roulette-discover, .poets, .quizzes {\n        background: rgba(72, 17, 57, 1);\n        padding: 1rem;\n        width: 100vw;\n        position: relative;\n        margin-left: -50vw;\n        margin-top: 100px;\n        left: 50%;\n        h1, h2 {\n            color: white\n        }\n        \n    }\n    h2 {\n        color: var(--plum);\n    }\n    .poets {\n        background-image: url('/themes/custom/lvp_barrio/assets/poet_bg.png') !important;\n        }\n    .quizzes {\n            background-image: url('/themes/custom/lvp_barrio/assets/quiz_bg.png') !important;\n        }\n    .poets .container, .quizzes .container {\n        padding: 0;\n    }\n}\n\n\n.plum-bg.roulette-discover